cd /tmp/vally-eval-trial-SyLPcX && mkdir -p docs/features/pricing tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount .copilot-tracking/skraft-plans/pricing/details/2026-08-12 && cat > docs/features/pricing/loyalty-discount.feature <<'EOF'
Feature: Loyalty discount

  Returning customers see the reduction earned by their loyalty tier in the checkout total.

  # Settled: Bronze, Silver and Gold (AC-1 to AC-4).
  # NOT decided, deliberately without a scenario: the Platinum tier reduction, and any
  # reduction rounding beyond the 7-cent Bronze example (see test plan "Open questions").

  @loyalty-discount @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze reduced total
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Silver customer is charged the Silver reduced total
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Gold customer is charged the Gold reduced total
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @loyalty-discount @edge-case
  Scenario: Bronze customer with a tiny basket is charged a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_reduced_total()
    {
        // Bronze customer is charged the Bronze reduced total
        var calculateLoyaltyDiscount = new CalculateLoyaltyDiscount();

        var quote = calculateLoyaltyDiscount.Handle(
            new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
cd tests/CheckoutPricing.UnitTest && dotnet test --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -20

